import io
import json
import os
import subprocess
import sys
import tempfile
from pathlib import Path
from types import SimpleNamespace

sys.dont_write_bytecode = True
SKILL = Path("token-master-plugin/skills/token-master")

from brainspace import headroom, tokens  # noqa: E402
from brainspace.runtime import RuntimeSession  # noqa: E402

Failure = headroom.HeadroomWorkerFailure
assert issubclass(Failure, ValueError)
for value in ("RuntimeError", None):
    error = Failure(value)
    assert str(error) == "headroom_worker_reported_failure" and error.error_type == value

IDENTITY = "a" * 64
OLD = "comparator response identity or status mismatch"
RealContainer = headroom.HeadroomContainer


class Process:
    def __init__(self):
        self.stdin = io.BytesIO()
        self.returncode = None

    def wait(self, timeout):
        if self.returncode is None:
            raise subprocess.TimeoutExpired("fake attach", timeout)
        return self.returncode

    def poll(self):
        return self.returncode

    def terminate(self):
        self.returncode = -15

    def kill(self):
        self.returncode = -9


class Thread:
    def __init__(self, target, daemon):
        self.target = target

    def start(self):
        if self.target.__name__ != "_read":
            self.target()


def boundary(worker):
    mounts = {"/inputs/worker.py": worker.directory / "worker-frozen.py",
              "/inputs/assets.json": worker.assets, "/cache": worker.cache}
    env = {**headroom.TASK_ENVIRONMENT, **headroom.PINNED_BASE_ENVIRONMENT}
    return {
        "Id": IDENTITY, "Image": headroom.IMAGE_ID,
        "Config": {"Labels": {"tokenmaster.parity": worker.label}, "User": "65532:65532",
                   "Entrypoint": ["python"], "Cmd": ["/inputs/worker.py"], "OpenStdin": True,
                   "Volumes": {"/home/nonroot/.headroom": {}},
                   "Env": [key + "=" + value for key, value in env.items()]},
        "HostConfig": {"NetworkMode": "none", "ReadonlyRootfs": True, "Privileged": False,
                       "CapDrop": ["ALL"], "SecurityOpt": ["no-new-privileges"],
                       "NanoCpus": 2_000_000_000, "Memory": 4 * 1024**3, "MemorySwap": 4 * 1024**3,
                       "PidsLimit": 256, "Tmpfs": {"/tmp": "rw,noexec,nosuid,nodev,size=256m",
                                                   "/home/nonroot/.headroom": "rw,noexec,nosuid,nodev,size=64m"}},
        "Mounts": [{"Type": "bind", "Destination": t, "Source": str(p), "RW": False} for t, p in mounts.items()],
        "State": {"Running": False, "ExitCode": 0},
    }


def started_worker(ready_changes=None, start=True):
    tmp = Path(tempfile.mkdtemp())
    (tmp / "cache").mkdir()
    (tmp / "assets.json").write_text("{}", encoding="utf-8")
    (tmp / "docker").mkdir()
    (tmp / "docker" / "config.json").write_text("{}", encoding="utf-8")
    headroom.shutil = SimpleNamespace(which=lambda _: "fake-docker")
    worker = RealContainer(tmp / "task", cache=tmp / "cache", assets=tmp / "assets.json",
                           docker_config=tmp / "docker", label="check-task")
    process = Process()

    def command(args, *, timeout=30, check=True):
        if args[:2] == ["image", "inspect"]:
            value = [{"Id": headroom.IMAGE_ID, "Config": {"Labels": {
                "org.opencontainers.image.revision": headroom.COMMIT}}}]
        elif args[0] == "create":
            return SimpleNamespace(returncode=0, stdout=IDENTITY + "\n")
        elif args[0] == "inspect":
            value = [boundary(worker)]
        else:
            value = {}
        return SimpleNamespace(returncode=0, stdout=json.dumps(value))

    def popen(args, **kwargs):
        ready = dict(id="ready", ok=True, protocol="headroom-task-worker-v1", commit=headroom.COMMIT,
                     model_revision=headroom.MODEL_REVISION, worker_sha256=worker.worker_sha256)
        ready.update(ready_changes or {})
        worker.replies.put(ready)
        return process

    worker.command = command
    headroom.threading = SimpleNamespace(Thread=Thread)
    headroom.subprocess = SimpleNamespace(Popen=popen, PIPE=subprocess.PIPE,
                                          TimeoutExpired=subprocess.TimeoutExpired)
    assert worker.worker_error_type is None
    if start:
        worker.start()
    return worker


def worker_failure(frame):
    worker = started_worker()
    worker.replies.put(frame)
    try:
        worker.prepare({"model": "fixture", "messages": []})
    except Exception as error:  # noqa: BLE001
        return worker, error
    raise AssertionError("prepare accepted a failed frame")


# Worker-reported failures: expected id with ok exactly False.
for reported, expected in (("ResponseFrameOverflow", "ResponseFrameOverflow"), ("_x9", "_x9"),
                           ("A" * 128, "A" * 128), (None, None), (7, None), ("", None),
                           ("bad type!", None), ("9Lives", None), ("A" * 129, None),
                           ("RuntimeError\n", None), ("Erreur_\u00e9", None)):
    frame = {"id": "1", "ok": False}
    if reported is not None:
        frame["error_type"] = reported
    worker, error = worker_failure(frame)
    assert type(error) is Failure, (reported, type(error))
    assert str(error) == "headroom_worker_reported_failure"
    assert error.error_type == worker.worker_error_type == expected, (reported, error.error_type)
    assert worker.failed
    try:
        worker.finish()
        raise AssertionError("failed worker accepted another request")
    except RuntimeError:
        pass

# Protocol mismatches keep the old, generic error.
for frame in ({"id": "foreign", "ok": False, "error_type": "ValueError"}, {"id": "1", "ok": True},
              {"id": "1", "ok": "false", "error_type": "ValueError"}, {"id": "1", "ok": 0, "error_type": "X"},
              ["not", "a", "dict"]):
    worker, error = worker_failure(frame)
    assert type(error) is ValueError and str(error) == OLD, frame
    assert worker.failed and worker.worker_error_type is None

# Failed ready handshake is a worker-reported failure too.
worker = started_worker({"ok": False, "error_type": "AssertionError"}, start=False)
try:
    worker.start()
    raise AssertionError("start accepted a failed ready frame")
except Failure as error:
    assert error.error_type == worker.worker_error_type == "AssertionError" and worker.failed
worker = started_worker({"id": "other"}, start=False)
try:
    worker.start()
    raise AssertionError("start accepted a foreign ready frame")
except ValueError as error:
    assert type(error) is ValueError and str(error) == OLD

# Runtime records the sanitized worker type only for worker-reported failures.
headroom.HeadroomContainer = RealContainer


class Transport:
    model = "offline-check"
    max_request_bytes = 524288
    max_output_tokens = 2048

    def encode(self, chat):
        return tokens.serialize({"request": chat})

    def send(self, wire):
        raise AssertionError("no model call expected")


def session_failure(failure, *, on_start=False):
    class Backend:
        def __init__(self, directory, **kwargs):
            directory.mkdir()

        def start(self):
            if on_start:
                raise failure
            return {"ready": True}

        def prepare(self, chat, **kwargs):
            raise failure

        def finish(self):
            return {}

        def close(self):
            return {"container_id": None, "container_removed": True}

    headroom.HeadroomContainer = Backend
    tmp = Path(tempfile.mkdtemp())
    (tmp / "workspace").mkdir()
    session = RuntimeSession(workspace=tmp / "workspace", output=tmp / "runtime", session_id="check",
                             backend="headroom", transport=Transport(),
                             headroom_options={"cache": tmp / "cache", "assets": tmp / "assets",
                                               "docker_config": None})
    try:
        if on_start:
            session.prepare_components()
        else:
            session.invoke({"model": Transport.model, "messages": [{"role": "user", "content": "x"}]},
                           intent="overview")
        raise AssertionError("component failure was not raised")
    except type(failure):
        pass
    result = session.finish()
    session.close()
    return result["component"]["failure"]


assert session_failure(Failure("RuntimeError")) == {
    "phase": "headroom_prepare", "error_type": "HeadroomWorkerFailure", "worker_error_type": "RuntimeError"}
assert session_failure(Failure(None)) == {"phase": "headroom_prepare", "error_type": "HeadroomWorkerFailure"}
assert session_failure(ValueError(OLD)) == {"phase": "headroom_prepare", "error_type": "ValueError"}
