import ast
import hashlib
import subprocess
import sys
from pathlib import Path

SKILL = Path("token-master-plugin/skills/token-master")
BRAIN = SKILL / "brainspace"
sys.path.insert(0, str(SKILL.resolve()))


def parse(name):
    return ast.parse((BRAIN / name).read_text(encoding="utf-8"))


def used_names(tree):
    return {node.id for node in ast.walk(tree) if isinstance(node, ast.Name)}


policy = parse("request_policy.py")
functions = {node.name: node for node in policy.body if isinstance(node, ast.FunctionDef)}
assert "is_json_value" in functions, "request_policy.is_json_value is missing"
assert "_json_value" not in functions, "request_policy still defines _json_value"
assert "_json_value" not in used_names(policy), "request_policy still references _json_value"
for node in ast.walk(policy):
    if isinstance(node, (ast.Assign, ast.AnnAssign)):
        targets = node.targets if isinstance(node, ast.Assign) else [node.target]
        assert not any(isinstance(t, ast.Name) and t.id == "_json_value" for t in targets), \
            "a _json_value alias was kept"
signature = functions["is_json_value"].args
assert [a.arg for a in signature.args] == ["value"], "is_json_value must take exactly one argument"
assert not (signature.kwonlyargs or signature.vararg or signature.kwarg or signature.posonlyargs)

expected_imports = {
    "native_events.py": {"SourceReadInfo", "_protected", "_tool_indices", "is_json_value"},
    "native_responses.py": {"_protected", "_tool_indices", "is_json_value"},
}
for name, wanted in expected_imports.items():
    tree = parse(name)
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.level == 1 and node.module == "request_policy":
            imported |= {alias.name for alias in node.names}
    assert imported == wanted, (name, sorted(imported))
    assert "_json_value" not in used_names(tree), name + " still references _json_value"

# The read-only host's own, unrelated validator must be untouched.
