assert hashlib.sha256(host_bytes).hexdigest() == \
    "864ab5e77332f3950d4598cb14ce46ee0e5746e72369fdb9d7987ec7940d378a", \
    "readonly_learning_host.py was modified"

from brainspace import native_events, native_responses, readonly_learning_host, request_policy  # noqa: E402

assert not hasattr(request_policy, "_json_value"), "request_policy still exposes _json_value"
