assert native_responses._wire({"b": 1, "a": [True]}) == '{"a":[true],"b":1}'
try:
    native_responses._wire({"a": (1,)})
except ValueError as error:
    assert str(error) == "native codec requires JSON values", str(error)
else:
    raise AssertionError("native_responses._wire accepted a tuple")
try:
    request_policy._tool_indices({"messages": [{"role": "user", "content": "x"}], "x": float("nan")})
except ValueError as error:
    assert str(error) == "not a JSON envelope"
else:
    raise AssertionError("_tool_indices accepted a non-JSON envelope")
assert readonly_learning_host._json_value({"a": [1]}) is None
try:
